CREATE TABLE IF NOT EXISTS release_tasks (
 id TEXT PRIMARY KEY, date TEXT NOT NULL, account TEXT NOT NULL,
 owner_id TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL DEFAULT '',
 payload TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0,
 deleted INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS release_tasks_owner_date ON release_tasks(owner_id,date,deleted);
